void rover_policy(const float raw[32], float action[6]) {
    float x[32], h0[64], h1[64];
    for (int i=0; i<32; ++i) x[i] = raw[i]/scale[i];
    for (int j=0; j<64; ++j) {
        float v = b0[j];
        for (int k=0; k<32; ++k) v += w0[j*32+k]*x[k];
        h0[j] = tanhf(v);
    }
    for (int j=0; j<64; ++j) {
        float v = b1[j];
        for (int k=0; k<64; ++k) v += w1[j*64+k]*h0[k];
        h1[j] = tanhf(v);
    }
    for (int j=0; j<6; ++j) {
        float v = b2[j];
        for (int k=0; k<64; ++k) v += w2[j*64+k]*h1[k];
        action[j] = clip(v, -1.0f, 1.0f);
    }
}
void rover_targets(const float raw[32], float separation, float radius, float targets[6]) {
    float action[6];
    rover_policy(raw, action);
    for (int i=0; i<6; ++i) {
        float base = (raw[0] + (i<3 ? -1.0f : 1.0f)*raw[1]*separation*0.5f)/radius;
        targets[i] = clip(base + 5.0f*action[i], -0x1.a63ae40000000p+4f, 0x1.a63ae40000000p+4f);
    }
}
